usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Certificates.Get(
		context.TODO(),
		"certificate_id",
		openai.AdminOrganizationCertificateGetParams{
			Include: []string{"content"},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
